#############################################
## DBsubject()
## DBchapter()
## DBsection()
## Level()
## KEYWORDS()
## TitleText1()
## EditionText1()
## AuthorText1()
## Section1(not reported)
## Problem1(1.14)
## Author()
## Institution()
## Language(en-US)

DOCUMENT();

############################################################
# Load Macros
############################################################
loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PCCmacros.pl",
  "PGessaymacros.pl",
  "contextForm.pl",
  "APEX.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

############################################################
# Header
############################################################

############################################################
# PG Setup Code
############################################################
$a=non_zero_random(-4,4,1);
$low = int(($a)**2/3)+1;
$b=random($low,9,1);
$c=non_zero_random(-3,3,1);
if($envir{problemSeed}==1){$a=1;$b=1;$c=-1;};
$f=Formula("x^3+$a x^2+$b x + $c");
$fp=$f->D('x');
Context("Numeric")->flags->set(tolType=>'absolute',tolerance=>0.005);
$r=0;
do {
  $r=$r-($f->eval(x=>$r))/($fp->eval(x=>$r));
} until ($r==$r-($f->eval(x=>$r))/($fp->eval(x=>$r)));
if ($r>0) {
  $A=int($r*10)/10;
  $B=$A+0.1;
} else {
  $B=int($r*10)/10;
  $A=$B-0.1;
};
$showwork = '[@ explanation_box(message => "Show the steps you used applying the Bisection Method.") @]*';

############################################################
# Body
############################################################

BEGIN_PGML
Use the Bisection Method to approximate, accurate to two decimal places, the root of [`g(x) = [$f]`] on [`[[$A],[$B]]\text{.}`]

[@KeyboardInstructions('Enter the approximation:')@]**

[_]{$r}{10}

[$showwork]**

END_PGML

############################################################
# End Problem
############################################################

ENDDOCUMENT();
